package net.civeira.phylax.feature.template.snippetversion.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.snippetversion.domain.SnippetVersion;
import net.civeira.phylax.feature.template.snippetversion.domain.valueobject.LocaleVO;

class LocaleValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of locale of snippet version")
  void test_locale_value_holder_assign_plain_value() {
    Object holder = new Object();
    LocaleValueHolder<Object> value = new LocaleValueHolder<>(holder);
    Assertions.assertSame(holder, value.locale("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLocaleValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getLocale().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.localeNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLocaleValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getLocale().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of locale of snippet version")
  void test_locale_value_holder_assign_value_object() {
    Object holder = new Object();
    LocaleValueHolder<Object> value = new LocaleValueHolder<>(holder);
    LocaleVO vo = LocaleVO.from("one");
    Assertions.assertFalse(value.getLocaleValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.locale(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLocaleValue().orElseThrow());
    Assertions.assertSame(holder, value.locale(Optional.empty()));
    Assertions.assertFalse(value.getLocaleValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.locale(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLocaleValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of locale of snippet version against the original")
  void test_locale_value_holder_read() {
    Object holder = new Object();
    LocaleValueHolder<Object> value = new LocaleValueHolder<>(holder);
    LocaleVO vo = LocaleVO.from("one");
    LocaleVO other = LocaleVO.from("one");
    SnippetVersion original = Mockito.mock(SnippetVersion.class);
    Mockito.when(original.getLocaleValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLocale(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLocale(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.locale(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLocale(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLocale(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of locale of snippet version")
  void test_locale_value_holder_unset() {
    Object holder = new Object();
    LocaleValueHolder<Object> value = new LocaleValueHolder<>(holder);
    LocaleVO vo = LocaleVO.from("one");
    value.locale(vo);
    Assertions.assertSame(holder, value.unsetLocaleIfMatches("locale_other"));
    Assertions.assertTrue(value.getLocaleValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLocaleIfMatches("locale"));
    Assertions.assertFalse(value.getLocaleValue().isPresent(),
        "The field name must clear the value");
    value.locale(vo);
    Assertions.assertSame(holder, value.unsetLocale());
    Assertions.assertFalse(value.getLocaleValue().isPresent(), "Unset must clear the value");
  }
}
